static int is_connected(enum ib_qp_type qp_type) /* <=== is_connected */ 
{
	if (qp_type == IB_QPT_RC || qp_type == IB_QPT_UC)
		return 1;

	return 0;
}

void mlx5_core_destroy_rq_tracked(struct mlx5_core_dev *dev, /* <=== mlx5_core_destroy_rq_tracked */ 
				  struct mlx5_core_qp *rq)
{
	destroy_resource_common(dev, rq);
	mlx5_core_destroy_rq(dev, rq->qpn);
}

static void spin_unlock(spinlock_t *lock) /* <=== spin_unlock */ 
{
	int ret = pthread_spin_unlock(lock);
	assert(!ret);
}

static inline void spin_lock(spinlock_t *lock) /* <=== spin_lock */ 
{
	/*
	 * Spin locks also need to be removed in order to eliminate all
	 * memory barriers. They are only used by the write side anyway.
	 */
#ifndef NO_SYNC_SMP_MB
	preempt_disable();
	lock_impl_lock(&lock->internal_lock);
#endif
}

